import"./chunk-2NFLSA4Y.js";var t={standingWaves:{theory:{concept:"[[A standing wave is the oscillation pattern formed when two waves of equal frequency and amplitude travel in opposite directions through the same medium and overlap.]]"},section:{formation:{title:"How a standing wave forms",text:"A wave reflecting from a fixed end travels back along the string. The incoming and reflected waves have the same frequency and amplitude and travel in opposite directions. Their superposition makes a pattern that stays in place while the string oscillates."},nodes:{title:"Nodes and antinodes",text:"[[A node is a point that stays still at all times.]] The fixed ends are always nodes. Between each pair of neighbouring nodes is an antinode, where the string reaches its largest displacement. The separation between neighbouring nodes is half a wavelength."},harmonics:{title:"Harmonics on a string",text:"[[Only certain patterns fit a string fixed at both ends: the length must contain a whole number of half-wavelengths.]] The simplest pattern is the fundamental (n = 1); the next patterns are the second, third and higher harmonics. Harmonic n has n loops and n internal half-wave sections."},resonance:{title:"Resonance and frequency",text:"Each harmonic has its own resonant frequency. For a fixed string and wave speed, higher harmonics vibrate faster. Changing the string length or wave speed changes the resonant frequencies; shortening the string or increasing wave speed raises them."},energy:{title:"A pattern that does not travel",text:"The shape of a standing wave does not move along the string, although every point between nodes moves up and down. In the ideal model there is no damping, so the oscillation continues with constant amplitude. Real strings lose energy and need continued driving."},check:{title:"Check your understanding",text:"How many antinodes are there in the third harmonic? (Three.) How far apart are neighbouring nodes? (Half a wavelength.) Why must a fixed-end string have nodes at both ends? (The ends cannot move.) Change the harmonic, length and wave speed to test the pattern and frequency."}},formula:{shape:"Displacement along a string vibrating in harmonic n",wavelength:"Wavelength of harmonic n on a string of length L",frequency:"Resonant frequency of harmonic n",positions:"Positions of nodes and antinodes, where j is an integer"},variable:{position:"Position along the string"},assumption:{string:"The string is uniform, perfectly flexible and fixed exactly at both ends; the wave speed is constant.",resonance:"Only ideal resonant modes are shown. Damping, reflections during startup and the driving source are not simulated.",amplitude:"The string oscillates in the small-displacement linear regime; A is the maximum antinode displacement and remains constant."},param:{harmonic:"Harmonic number",amplitude:"Maximum amplitude at an antinode",length:"Length of the string",speed:"Wave speed on the string",timeStep:"Time step"},hint:{harmonic:"The harmonic number is the number of loops (antinodes) between the fixed ends.",amplitude:"The largest distance an antinode moves from its resting line.",length:"Distance between the two fixed ends.",speed:"How fast a travelling wave moves along the string; it sets each harmonic's resonant frequency."},preset:{fundamental:"Fundamental \xB7 1 loop",second:"Second harmonic \xB7 2 loops",third:"Third harmonic \xB7 3 loops"},measure:{frequency:"Resonant frequency",wavelength:"Wavelength",nodeCount:"Number of nodes, including fixed ends",antinodeCount:"Number of antinodes",maximumDisplacement:"Maximum antinode displacement",period:"Oscillation period",probeDisplacement:"Displacement at the string's midpoint",probeAmplitude:"Maximum displacement at the midpoint"},graph:{probe:"Midpoint displacement over time"},view:{profileOption:"Show the vibrating string",nodesOption:"Mark nodes and antinodes",probeOption:"Show the midpoint probe",equilibriumOption:"Show the resting position",mode:"Harmonic {harmonic} \xB7 fixed ends",nodes:"\u25CF Nodes",antinodes:"\u25C6 Antinodes",probe:"Midpoint: {value}",nodeSpacing:"Node spacing = {value} (\u03BB/2)",fixedEnd:"Fixed"},challenge:{fundamental:{title:"Find the fundamental",description:"Make a pattern with one antinode and two nodes.",hint:"Choose harmonic 1."},threeLoops:{title:"Fit three loops",description:"Make three antinodes fit between the fixed ends.",hint:"The harmonic number equals the number of antinodes."},frequency:{title:"Reach 2 Hz",description:"Set the string's resonant frequency to 2 Hz.",hint:"Frequency is harmonic number times wave speed divided by twice the string length."},wavelength:{title:"Set a 3 m wavelength",description:"Choose a mode and string length that give a wavelength of 3 m.",hint:"Wavelength is twice the string length divided by the harmonic number."},midpoint:{title:"Make a midpoint node",description:"Choose a mode where the string's midpoint remains still.",hint:"Even harmonics have a node at the midpoint."}}}},i={sim:t};export{i as default,t as sim};
